#[derive(Debug, Clone, PartialEq, Default)]
pub struct Destructible {
    /// `DEST`, required.
    pub header: Option<Sub<DestructibleHeader>>,
    /// `DAMC`, optional.
    pub resistances: Option<Sub<DestructibleResistances>>,
    /// `DSDL`, optional.
    pub secondary_damage_list: Option<Sub<FormId>>,
    /// Group `Stage`, repeated.
    pub stage: Vec<DestructibleStage>,
}

impl Destructible {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"DEST",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"DAMC",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"DSDL",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: DestructibleStage::MEMBERS,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.header,
                    subs,
                    *index,
                    "Destructible.DEST",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 1, index } => put(
                    &mut self.resistances,
                    subs,
                    *index,
                    "Destructible.DAMC",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 2, index } => put(
                    &mut self.secondary_damage_list,
                    subs,
                    *index,
                    "Destructible.DSDL",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 3, hits } => {
                    let mut group = DestructibleStage::default();
                    group.fill(hits, subs, ctx, extra);
                    self.stage.push(group);
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"DEST", self.header.as_ref());
        emit(out, *b"DAMC", self.resistances.as_ref());
        emit(out, *b"DSDL", self.secondary_damage_list.as_ref());
        for group in &self.stage {
            group.emit(out);
        }
    }
}

impl Visit for Destructible {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.resistances, "Destructible.DAMC", out);
        visit_form_ids(&self.secondary_damage_list, "Destructible.DSDL", out);
        visit_form_ids(&self.stage, "Destructible.Stage", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.resistances, "Destructible.DAMC", out);
        visit_form_ids_mut(&mut self.secondary_damage_list, "Destructible.DSDL", out);
        visit_form_ids_mut(&mut self.stage, "Destructible.Stage", out);
    }
}

