#[derive(Debug, Clone, PartialEq, Default)]
pub struct ObteBlock {
    /// `OBTE`, optional.
    pub combination_count: Option<Sub<u32>>,
    /// Group `Combination`, repeated.
    pub combination: Vec<ObteBlockCombination>,
    /// `STOP`, required.
    pub end_marker: Option<Sub<Empty>>,
}

impl ObteBlock {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"OBTE",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: ObteBlockCombination::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"STOP",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.combination_count,
                    subs,
                    *index,
                    "ObteBlock.OBTE",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 1, hits } => {
                    let mut group = ObteBlockCombination::default();
                    group.fill(hits, subs, ctx, extra);
                    self.combination.push(group);
                }
                Hit::Sub { member: 2, index } => put(
                    &mut self.end_marker,
                    subs,
                    *index,
                    "ObteBlock.STOP",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"OBTE", self.combination_count.as_ref());
        for group in &self.combination {
            group.emit(out);
        }
        emit(out, *b"STOP", self.end_marker.as_ref());
    }
}

impl Visit for ObteBlock {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.combination, "ObteBlock.Combination", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.combination, "ObteBlock.Combination", out);
    }

    fn visit_lstrings<'a>(&'a self, _path: &'static str, out: &mut LStrings<'a>) {
        visit_lstrings(&self.combination, "ObteBlock.Combination", out);
    }

    fn visit_lstrings_mut<'a>(&'a mut self, _path: &'static str, out: &mut LStringsMut<'a>) {
        visit_lstrings_mut(&mut self.combination, "ObteBlock.Combination", out);
    }
}

