#[derive(Debug, Clone, PartialEq)]
pub struct AmmoData {
    pub value: u32,
    /// Present only when bytes remain in the payload.
    pub weight: Option<f32>,
}

impl Field for AmmoData {
    fn read(r: &mut Reader<'_>, _field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        let f0 = u32::read(r, "AMMO.DATA.Value", ctx)?;
        let f1 = if !r.is_empty() {
            Some(f32::read(r, "AMMO.DATA.Weight", ctx)?)
        } else {
            None
        };
        Ok(Self {
            value: f0,
            weight: f1,
        })
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.value.write(out);
        if let Some(value) = &self.weight {
            value.write(out);
        }
    }
}

impl Visit for AmmoData {}

