#[derive(Debug, Clone, PartialEq, Default)]
pub struct AmmoRecord {
    /// `EDID`, required.
    pub editor_id: Option<Sub<ZString>>,
    /// `VMAD`, optional.
    pub scripts: Option<Sub<Bytes>>,
    /// `OBND`, required.
    pub object_bounds: Option<Sub<AmmoObjectBounds>>,
    /// `ODTY`, required.
    pub dirtiness_scale: Option<Sub<f32>>,
    /// `SNTP`, optional.
    pub snap_template: Option<Sub<FormId>>,
    /// `SNBH`, optional.
    pub snap_behavior: Option<Sub<FormId>>,
    /// `DEFL`, optional.
    pub default_layer: Option<Sub<FormId>>,
    /// `XALG`, optional.
    pub xalg_flags: Option<Sub<u64>>,
    /// `PTT2`, optional.
    pub transforms: Option<Sub<AmmoTransforms>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// Group `Model`, required.
    pub model: Option<Model>,
    /// Group `Destructible`, optional.
    pub destructible: Option<Destructible>,
    /// `PUSH`, optional.
    pub pickup_sound: Option<Sub<SoundReference>>,
    /// `PDSH`, optional.
    pub putdown_sound: Option<Sub<SoundReference>>,
    /// `DESC`, required.
    pub description: Option<Sub<LString>>,
    /// Group `Keywords`, optional.
    pub keywords: Option<Keywords>,
    /// `DATA`, required.
    pub data: Option<Sub<AmmoData>>,
    /// `DNAM`, required.
    pub ammo_data: Option<Sub<AmmoAmmoData>>,
    /// `ONAM`, optional.
    pub short_name: Option<Sub<LString>>,
    /// `NAM1`, optional.
    pub casing_model: Option<Sub<ZString>>,
    /// `FLLD`, required.
    pub casing_light_layer: Option<Sub<AmmoCasingLightLayer>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl AmmoRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"VMAD",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"OBND",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ODTY",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"SNTP",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"SNBH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"DEFL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"XALG",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PTT2",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Required,
            members: Model::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Destructible::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"PUSH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PDSH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"DESC",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: Keywords::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"DNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ONAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"NAM1",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"FLLD",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "AMMO.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scripts, subs, *index, "AMMO.VMAD", ctx, extra)
                }
                Hit::Sub { member: 2, index } => put(
                    &mut self.object_bounds,
                    subs,
                    *index,
                    "AMMO.OBND",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 3, index } => put(
                    &mut self.dirtiness_scale,
                    subs,
                    *index,
                    "AMMO.ODTY",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 4, index } => put(
                    &mut self.snap_template,
                    subs,
                    *index,
                    "AMMO.SNTP",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 5, index } => put(
                    &mut self.snap_behavior,
                    subs,
                    *index,
                    "AMMO.SNBH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 6, index } => put(
                    &mut self.default_layer,
                    subs,
                    *index,
                    "AMMO.DEFL",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 7, index } => {
                    put(&mut self.xalg_flags, subs, *index, "AMMO.XALG", ctx, extra)
                }
                Hit::Sub { member: 8, index } => {
                    put(&mut self.transforms, subs, *index, "AMMO.PTT2", ctx, extra)
                }
                Hit::Group { member: 9, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 10, index } => {
                    put(&mut self.name, subs, *index, "AMMO.FULL", ctx, extra)
                }
                Hit::Group { member: 11, hits } if self.model.is_none() => {
                    let mut group = Model::default();
                    group.fill(hits, subs, ctx, extra);
                    self.model = Some(group);
                }
                Hit::Group { member: 12, hits } if self.destructible.is_none() => {
                    let mut group = Destructible::default();
                    group.fill(hits, subs, ctx, extra);
                    self.destructible = Some(group);
                }
                Hit::Sub { member: 13, index } => put(
                    &mut self.pickup_sound,
                    subs,
                    *index,
                    "AMMO.PUSH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 14, index } => put(
                    &mut self.putdown_sound,
                    subs,
                    *index,
                    "AMMO.PDSH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 15, index } => {
                    put(&mut self.description, subs, *index, "AMMO.DESC", ctx, extra)
                }
                Hit::Group { member: 16, hits } if self.keywords.is_none() => {
                    let mut group = Keywords::default();
                    group.fill(hits, subs, ctx, extra);
                    self.keywords = Some(group);
                }
                Hit::Sub { member: 17, index } => {
                    put(&mut self.data, subs, *index, "AMMO.DATA", ctx, extra)
                }
                Hit::Sub { member: 18, index } => {
                    put(&mut self.ammo_data, subs, *index, "AMMO.DNAM", ctx, extra)
                }
                Hit::Sub { member: 19, index } => {
                    put(&mut self.short_name, subs, *index, "AMMO.ONAM", ctx, extra)
                }
                Hit::Sub { member: 20, index } => put(
                    &mut self.casing_model,
                    subs,
                    *index,
                    "AMMO.NAM1",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 21, index } => put(
                    &mut self.casing_light_layer,
                    subs,
                    *index,
                    "AMMO.FLLD",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"VMAD", self.scripts.as_ref());
        emit(out, *b"OBND", self.object_bounds.as_ref());
        emit(out, *b"ODTY", self.dirtiness_scale.as_ref());
        emit(out, *b"SNTP", self.snap_template.as_ref());
        emit(out, *b"SNBH", self.snap_behavior.as_ref());
        emit(out, *b"DEFL", self.default_layer.as_ref());
        emit(out, *b"XALG", self.xalg_flags.as_ref());
        emit(out, *b"PTT2", self.transforms.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"FULL", self.name.as_ref());
        if let Some(group) = &self.model {
            group.emit(out);
        }
        if let Some(group) = &self.destructible {
            group.emit(out);
        }
        emit(out, *b"PUSH", self.pickup_sound.as_ref());
        emit(out, *b"PDSH", self.putdown_sound.as_ref());
        emit(out, *b"DESC", self.description.as_ref());
        if let Some(group) = &self.keywords {
            group.emit(out);
        }
        emit(out, *b"DATA", self.data.as_ref());
        emit(out, *b"DNAM", self.ammo_data.as_ref());
        emit(out, *b"ONAM", self.short_name.as_ref());
        emit(out, *b"NAM1", self.casing_model.as_ref());
        emit(out, *b"FLLD", self.casing_light_layer.as_ref());
    }
}

