#[derive(Debug, Clone, PartialEq, Default)]
pub struct LvliRecord {
    /// `EDID`, required.
    pub editor_id: Option<Sub<ZString>>,
    /// `VMAD`, optional.
    pub scripts: Option<Sub<Bytes>>,
    /// `OBND`, required.
    pub object_bounds: Option<Sub<LvliObjectBounds>>,
    /// `ODTY`, required.
    pub dirtiness_scale: Option<Sub<f32>>,
    /// `OPDS`, optional.
    pub object_palette_defaults: Option<Sub<LvliObjectPaletteDefaults>>,
    /// `PTT2`, optional.
    pub transforms: Option<Sub<LvliTransforms>>,
    /// `SNBH`, optional.
    pub snap_behavior: Option<Sub<FormId>>,
    /// `DEFL`, optional.
    pub default_layer: Option<Sub<FormId>>,
    /// `XALG`, optional.
    pub xalg_flags: Option<Sub<u64>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `LVLD`, required.
    pub chance_none: Option<Sub<f32>>,
    /// `LVLM`, required.
    pub max_count: Option<Sub<u8>>,
    /// `LVLF`, required.
    pub flags: Option<Sub<LvliFlags>>,
    /// Group `Conditions`, repeated.
    pub conditions: Vec<Condition>,
    /// `LVLG`, optional.
    pub use_chance_none_global: Option<Sub<FormId>>,
    /// `LLRB`, optional.
    pub required_biome: Option<Sub<FormId>>,
    /// `LLRV`, optional.
    pub required_resource_vein: Option<Sub<FormId>>,
    /// `LLCT`, optional.
    pub entry_count: Option<Sub<u8>>,
    /// Group `Entries`, repeated.
    pub entries: Vec<LvliEntries>,
    /// `LLKC`, optional.
    pub filter_keyword_chances: Option<Sub<LvliFilterKeywordChances>>,
    /// `LVSG`, optional.
    pub epic_loot_chance: Option<Sub<FormId>>,
    /// `LIMC`, optional.
    pub marker_color: Option<Sub<LvliMarkerColor>>,
    /// `ONAM`, optional.
    pub override_name: Option<Sub<LString>>,
    /// `LVLL`, optional.
    pub legendary_item_default_list_rank: Option<Sub<u8>>,
    /// Group `Model`, required.
    pub model: Option<Model>,
    /// `FTYP`, optional.
    pub forced_location_ref_types: Option<Sub<LvliForcedLocationRefTypes>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl LvliRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"VMAD",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"OBND",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"ODTY",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"OPDS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PTT2",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"SNBH",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"DEFL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"XALG",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"LVLD",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"LVLM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"LVLF",
            card: Card::Required,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Condition::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"LVLG",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"LLRB",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"LLRV",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"LLCT",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: LvliEntries::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"LLKC",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"LVSG",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"LIMC",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ONAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"LVLL",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Required,
            members: Model::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"FTYP",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "LVLI.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scripts, subs, *index, "LVLI.VMAD", ctx, extra)
                }
                Hit::Sub { member: 2, index } => put(
                    &mut self.object_bounds,
                    subs,
                    *index,
                    "LVLI.OBND",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 3, index } => put(
                    &mut self.dirtiness_scale,
                    subs,
                    *index,
                    "LVLI.ODTY",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 4, index } => put(
                    &mut self.object_palette_defaults,
                    subs,
                    *index,
                    "LVLI.OPDS",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 5, index } => {
                    put(&mut self.transforms, subs, *index, "LVLI.PTT2", ctx, extra)
                }
                Hit::Sub { member: 6, index } => put(
                    &mut self.snap_behavior,
                    subs,
                    *index,
                    "LVLI.SNBH",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 7, index } => put(
                    &mut self.default_layer,
                    subs,
                    *index,
                    "LVLI.DEFL",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 8, index } => {
                    put(&mut self.xalg_flags, subs, *index, "LVLI.XALG", ctx, extra)
                }
                Hit::Group { member: 9, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 10, index } => {
                    put(&mut self.chance_none, subs, *index, "LVLI.LVLD", ctx, extra)
                }
                Hit::Sub { member: 11, index } => {
                    put(&mut self.max_count, subs, *index, "LVLI.LVLM", ctx, extra)
                }
                Hit::Sub { member: 12, index } => {
                    put(&mut self.flags, subs, *index, "LVLI.LVLF", ctx, extra)
                }
                Hit::Group { member: 13, hits } => {
                    let mut group = Condition::default();
                    group.fill(hits, subs, ctx, extra);
                    self.conditions.push(group);
                }
                Hit::Sub { member: 14, index } => put(
                    &mut self.use_chance_none_global,
                    subs,
                    *index,
                    "LVLI.LVLG",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 15, index } => put(
                    &mut self.required_biome,
                    subs,
                    *index,
                    "LVLI.LLRB",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 16, index } => put(
                    &mut self.required_resource_vein,
                    subs,
                    *index,
                    "LVLI.LLRV",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 17, index } => {
                    put(&mut self.entry_count, subs, *index, "LVLI.LLCT", ctx, extra)
                }
                Hit::Group { member: 18, hits } => {
                    let mut group = LvliEntries::default();
                    group.fill(hits, subs, ctx, extra);
                    self.entries.push(group);
                }
                Hit::Sub { member: 19, index } => put(
                    &mut self.filter_keyword_chances,
                    subs,
                    *index,
                    "LVLI.LLKC",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 20, index } => put(
                    &mut self.epic_loot_chance,
                    subs,
                    *index,
                    "LVLI.LVSG",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 21, index } => put(
                    &mut self.marker_color,
                    subs,
                    *index,
                    "LVLI.LIMC",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 22, index } => put(
                    &mut self.override_name,
                    subs,
                    *index,
                    "LVLI.ONAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 23, index } => put(
                    &mut self.legendary_item_default_list_rank,
                    subs,
                    *index,
                    "LVLI.LVLL",
                    ctx,
                    extra,
                ),
                Hit::Group { member: 24, hits } if self.model.is_none() => {
                    let mut group = Model::default();
                    group.fill(hits, subs, ctx, extra);
                    self.model = Some(group);
                }
                Hit::Sub { member: 25, index } => put(
                    &mut self.forced_location_ref_types,
                    subs,
                    *index,
                    "LVLI.FTYP",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"VMAD", self.scripts.as_ref());
        emit(out, *b"OBND", self.object_bounds.as_ref());
        emit(out, *b"ODTY", self.dirtiness_scale.as_ref());
        emit(out, *b"OPDS", self.object_palette_defaults.as_ref());
        emit(out, *b"PTT2", self.transforms.as_ref());
        emit(out, *b"SNBH", self.snap_behavior.as_ref());
        emit(out, *b"DEFL", self.default_layer.as_ref());
        emit(out, *b"XALG", self.xalg_flags.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"LVLD", self.chance_none.as_ref());
        emit(out, *b"LVLM", self.max_count.as_ref());
        emit(out, *b"LVLF", self.flags.as_ref());
        for group in &self.conditions {
            group.emit(out);
        }
        emit(out, *b"LVLG", self.use_chance_none_global.as_ref());
        emit(out, *b"LLRB", self.required_biome.as_ref());
        emit(out, *b"LLRV", self.required_resource_vein.as_ref());
        emit(out, *b"LLCT", self.entry_count.as_ref());
        for group in &self.entries {
            group.emit(out);
        }
        emit(out, *b"LLKC", self.filter_keyword_chances.as_ref());
        emit(out, *b"LVSG", self.epic_loot_chance.as_ref());
        emit(out, *b"LIMC", self.marker_color.as_ref());
        emit(out, *b"ONAM", self.override_name.as_ref());
        emit(
            out,
            *b"LVLL",
            self.legendary_item_default_list_rank.as_ref(),
        );
        if let Some(group) = &self.model {
            group.emit(out);
        }
        emit(out, *b"FTYP", self.forced_location_ref_types.as_ref());
    }
}

